CREATE TABLE "document_counters" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "document_counters_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"kind" "document_counters_kind" NOT NULL,
	"lastNumber" integer DEFAULT 0 NOT NULL,
	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "document_counters_kind_unique" UNIQUE("kind")
);
--> statement-breakpoint
CREATE TABLE "payment_refunds" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payment_refunds_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"paymentId" integer NOT NULL,
	"amount" integer NOT NULL,
	"refundedOn" date NOT NULL,
	"reason" varchar(500) NOT NULL,
	"reference" varchar(100),
	"recordedByUserId" integer NOT NULL,
	"cancelledAt" timestamp with time zone,
	"cancelledByUserId" integer,
	"cancelReason" varchar(500),
	"createdAt" timestamp with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payment_refunds_amount_positive" CHECK ("amount" > 0)
);
--> statement-breakpoint
CREATE TABLE "payments" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"feeLineId" integer,
	"paymentRequestId" integer,
	"method" "payments_method" NOT NULL,
	"status" "payments_status" DEFAULT 'started' NOT NULL,
	"amount" integer NOT NULL,
	"paystackReference" varchar(64),
	"mode" "payments_mode",
	"receivedOn" date,
	"paidAt" timestamp with time zone,
	"receiptNumber" integer,
	"note" varchar(500),
	"recordedByUserId" integer,
	"cancelledAt" timestamp with time zone,
	"cancelledByUserId" integer,
	"cancelReason" varchar(500),
	"createdAt" timestamp with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payments_paystackReference_unique" UNIQUE("paystackReference"),
	CONSTRAINT "payments_receiptNumber_unique" UNIQUE("receiptNumber"),
	CONSTRAINT "payments_one_owner" CHECK (("feeLineId" is null) <> ("paymentRequestId" is null)),
	CONSTRAINT "payments_amount_positive" CHECK ("amount" > 0)
);
