-- Carry today's payments into the ledger (Backend schema, section 2). Each statement skips what is already there, so
-- running it again adds nothing. First, every fee marked paid becomes one paid payment for its amount: on Paystack with
-- its reference (and the mode its audit row recorded), or else as marked paid by hand (and who ticked it, when the
-- audit row names the same fee).
INSERT INTO "payments" ("feeLineId", "method", "status", "amount", "paystackReference", "mode", "receivedOn", "paidAt", "note", "recordedByUserId", "createdAt")
SELECT f."id",
  (CASE WHEN f."paidReference" IS NULL THEN 'other' ELSE 'paystack' END)::"payments_method",
  'paid'::"payments_status",
  f."amount",
  f."paidReference",
  (SELECT (CASE WHEN a."details" LIKE '%"mode":"test"%' THEN 'test' ELSE 'live' END)::"payments_mode"
     FROM "admin_access_audit_events" a
    WHERE f."paidReference" IS NOT NULL AND a."action" = 'engagement_fee_paid_online'
      AND a."details" LIKE '%"paystackReference":"' || f."paidReference" || '"%'
    ORDER BY a."id" DESC LIMIT 1),
  (f."paidAt" AT TIME ZONE 'Africa/Lagos')::date,
  f."paidAt",
  CASE WHEN f."paidReference" IS NULL THEN 'Marked paid before the ledger' END,
  CASE WHEN f."paidReference" IS NULL THEN (
    SELECT a."actorUserId" FROM "admin_access_audit_events" a JOIN "users" u ON u."id" = a."actorUserId"
     WHERE a."action" = 'engagement_fee_paid' AND a."details" LIKE '%"feeLineId":' || f."id"::text || ',%'
       AND a."details" LIKE '%"paid":true%'
     ORDER BY a."id" DESC LIMIT 1) END,
  f."paidAt"
FROM "engagement_fee_lines" f
WHERE f."paidAt" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "payments" p WHERE p."feeLineId" = f."id");--> statement-breakpoint
-- Every confirmed payment request (the Full Report, the Business Review) becomes one paid payment for its amount, with
-- the Paystack reference and mode from its note, or the team's note and who confirmed it.
INSERT INTO "payments" ("paymentRequestId", "method", "status", "amount", "paystackReference", "mode", "receivedOn", "paidAt", "note", "recordedByUserId", "createdAt")
SELECT r."id",
  (CASE WHEN r."note" LIKE '%Paid online with Paystack, reference %' THEN 'paystack' ELSE 'other' END)::"payments_method",
  'paid'::"payments_status",
  r."amountNaira",
  substring(r."note" from 'Paid online with Paystack, reference (TS-[A-Z]+-[0-9]+-[0-9a-f]+)'),
  (CASE WHEN r."note" LIKE 'TEST: Paid online with Paystack, reference %' THEN 'test'
        WHEN r."note" LIKE 'Paid online with Paystack, reference %' THEN 'live' END)::"payments_mode",
  (COALESCE(r."confirmedAt", r."updatedAt") AT TIME ZONE 'Africa/Lagos')::date,
  COALESCE(r."confirmedAt", r."updatedAt"),
  CASE WHEN r."note" LIKE '%Paid online with Paystack, reference %' THEN NULL ELSE COALESCE(NULLIF(r."note", ''), 'Confirmed before the ledger') END,
  r."confirmedByUserId",
  COALESCE(r."confirmedAt", r."updatedAt")
FROM "payment_requests" r
WHERE r."status" = 'confirmed'
  AND NOT EXISTS (SELECT 1 FROM "payments" p WHERE p."paymentRequestId" = r."id");--> statement-breakpoint
-- Receipt numbers for every paid payment without one, in the order they were paid, after the last number given.
UPDATE "payments" AS p SET "receiptNumber" = numbered."number"
FROM (
  SELECT "id", (COALESCE((SELECT "lastNumber" FROM "document_counters" WHERE "kind" = 'receipt'), 0) + row_number() OVER (ORDER BY "paidAt", "id"))::integer AS "number"
  FROM "payments" WHERE "status" = 'paid' AND "receiptNumber" IS NULL
) AS numbered
WHERE p."id" = numbered."id";--> statement-breakpoint
INSERT INTO "document_counters" ("kind", "lastNumber")
SELECT 'receipt'::"document_counters_kind", max("receiptNumber") FROM "payments" HAVING max("receiptNumber") IS NOT NULL
ON CONFLICT ("kind") DO UPDATE SET "lastNumber" = GREATEST("document_counters"."lastNumber", EXCLUDED."lastNumber");--> statement-breakpoint
-- Invoice numbers for every fee with a payment and no number yet, in the order the fees were set.
UPDATE "engagement_fee_lines" AS f SET "invoiceNumber" = numbered."number"
FROM (
  SELECT l."id", (COALESCE((SELECT "lastNumber" FROM "document_counters" WHERE "kind" = 'invoice'), 0) + row_number() OVER (ORDER BY l."id"))::integer AS "number"
  FROM "engagement_fee_lines" l
  WHERE l."invoiceNumber" IS NULL AND EXISTS (SELECT 1 FROM "payments" p WHERE p."feeLineId" = l."id")
) AS numbered
WHERE f."id" = numbered."id";--> statement-breakpoint
INSERT INTO "document_counters" ("kind", "lastNumber")
SELECT 'invoice'::"document_counters_kind", max("invoiceNumber") FROM "engagement_fee_lines" HAVING max("invoiceNumber") IS NOT NULL
ON CONFLICT ("kind") DO UPDATE SET "lastNumber" = GREATEST("document_counters"."lastNumber", EXCLUDED."lastNumber");
